[
  {
    "statement": "Replacing or repairing damaged anti-predator nets is an action that can reduce predation by marine mammals at aquaculture systems.",
    "citations": [
      "2774"
    ]
  },
  {
    "statement": "One study found that replacing anti-predator nets more frequently at salmon farms resulted in fewer salmon losses to harbour seal predation.",
    "citations": [
      "2774"
    ]
  },
  {
    "statement": "Acoustic devices can be used at aquaculture systems.",
    "citations": [
      "2775"
    ]
  },
  {
    "statement": "Four of six studies found that acoustic devices reduced predation on caged salmon by grey seals, harbour seals and South American sea lions.",
    "citations": [
      "2775"
    ]
  },
  {
    "statement": "Some studies found that acoustic devices reduced the number of harbour seals approaching fish cages.",
    "citations": [
      "2775"
    ]
  },
  {
    "statement": "Two studies found that acoustic devices did not reduce harbour seal predation.",
    "citations": [
      "2775"
    ]
  },
  {
    "statement": "Two studies found that acoustic devices did not affect common bottlenose dolphin behavior around fin-fish farms.",
    "citations": [
      "2775"
    ]
  },
  {
    "statement": "Translocating mammals away from aquaculture systems has been attempted.",
    "citations": [
      "2776"
    ]
  },
  {
    "statement": "Studies found that more than half or nearly all of Australian and New Zealand fur seals translocated away from salmon farms returned.",
    "citations": [
      "2776"
    ]
  },
  {
    "statement": "Modifying anti-predator nets around aquaculture systems is a potential action to reduce predation.",
    "citations": [
      "2743"
    ]
  },
  {
    "statement": "Minimizing food waste at aquaculture systems is a potential action to reduce predation.",
    "citations": [
      "2744"
    ]
  },
  {
    "statement": "Introducing regulations to prevent the use of harmful deterrents is a potential action to reduce predation.",
    "citations": [
      "2746"
    ]
  },
  {
    "statement": "No studies were found evaluating the effectiveness of modifying anti-predator nets, minimizing food waste at aquaculture systems, or introducing regulations to prevent the use of harmful deterrents.",
    "citations": [
      "2743",
      "2744",
      "2746"
    ]
  }
]

[
  {
    "statement": "Several fishing gear modifications show effectiveness at reducing marine mammal entanglement.",
    "citations": []
  },
  {
    "statement": "Deploying fishing gear at different depths proved effective at reducing marine mammal entanglement.",
    "citations": [
      "2793"
    ]
  },
  {
    "statement": "A controlled study in the Arafura Sea found that fishing nets deployed 4.5 m below the water surface had fewer entanglements of dolphins than surface nets.",
    "citations": [
      "2793"
    ]
  },
  {
    "statement": "Acoustically reflective fishing gear materials demonstrated mixed but promising results in reducing marine mammal entanglement.",
    "citations": [
      "2807"
    ]
  },
  {
    "statement": "Two of three controlled studies found that fishing nets made from acoustically reflective materials, such as iron-oxide or barium sulfate, had fewer entanglements of harbour porpoises than conventional fishing nets.",
    "citations": [
      "2807"
    ]
  },
  {
    "statement": "One study found that barium sulfate nets did not reduce dolphin entanglements.",
    "citations": [
      "2807"
    ]
  },
  {
    "statement": "Catch and hook protection devices showed effectiveness for certain species.",
    "citations": [
      "2821"
    ]
  },
  {
    "statement": "One study in the South Pacific Ocean found that using cage or chain devices on fishing hooks resulted in fewer unwanted catches of toothed whales.",
    "citations": [
      "2821"
    ]
  },
  {
    "statement": "Several other modification approaches showed no evidence of effectiveness.",
    "citations": [
      "2801"
    ]
  },
  {
    "statement": "Stiffened materials or increased tension in fishing nets did not reduce Franciscana dolphin entanglements in one controlled study.",
    "citations": [
      "2801"
    ]
  },
  {
    "statement": "There are no available studies evaluating the effectiveness of biodegradable fishing gear on marine mammal populations.",
    "citations": [
      "2885"
    ]
  },
  {
    "statement": "There are no available studies evaluating the effectiveness of weakened fishing gear on marine mammal populations.",
    "citations": [
      "2797"
    ]
  },
  {
    "statement": "There are no available studies evaluating the effectiveness of smaller mesh sizes on marine mammal populations.",
    "citations": [
      "2802"
    ]
  },
  {
    "statement": "There are no available studies evaluating the effectiveness of limiting fishing gear length on marine mammal populations.",
    "citations": [
      "2795"
    ]
  }
]

[
  {
    "statement": "Studies have documented several population-level effects of legal protection for marine mammals and their habitats.",
    "citations": []
  },
  {
    "statement": "Legal habitat protection showed positive population responses in four studies across different regions.",
    "citations": [
      "2915"
    ]
  },
  {
    "statement": "A study in the North Atlantic Ocean found that Mediterranean monk seal populations increased during eight years after the islands the seals inhabited were legally protected.",
    "citations": [
      "2915"
    ]
  },
  {
    "statement": "A study in the South Pacific Ocean found that Hector's dolphin survival rates were higher after a coastal area was legally protected than before the area was protected.",
    "citations": [
      "2915"
    ]
  },
  {
    "statement": "One study in the North Sea found that bottlenose dolphin population size remained similar before and after part of the bottlenose dolphins' range was protected.",
    "citations": [
      "2915"
    ]
  },
  {
    "statement": "A study in the Port River estuary found that after legal protection, similar numbers of Indo-Pacific bottlenose dolphin strandings were recorded compared to before protection was in place.",
    "citations": [
      "2915"
    ]
  },
  {
    "statement": "A study in the Port River estuary found that after legal protection, human-caused strandings of Indo-Pacific bottlenose dolphins decreased.",
    "citations": [
      "2915"
    ]
  },
  {
    "statement": "Prohibiting hunting of marine mammal species demonstrated strong population effects in five studies.",
    "citations": [
      "2780"
    ]
  },
  {
    "statement": "Four of five studies found that after hunting was prohibited, harbor seal and humpback whale abundance increased over 7-30 years in the Kattegat and Skagerrak Seas, South Pacific Ocean, North Atlantic Ocean, and Southern Ocean.",
    "citations": [
      "2780"
    ]
  },
  {
    "statement": "One review covering the North Atlantic Ocean, North Pacific Ocean and Southern Hemisphere found significant increase rates for 10 of 12 baleen whale populations during 7-21 years after legislation prohibiting hunting was introduced.",
    "citations": [
      "2780"
    ]
  },
  {
    "statement": "One study found that mature male sperm whale numbers did not differ significantly before or 31 years after hunting was prohibited.",
    "citations": [
      "2780"
    ]
  },
  {
    "statement": "Prohibiting activities that cause disturbance in sensitive areas showed positive effects in limited studies.",
    "citations": [
      "2917"
    ]
  },
  {
    "statement": "One study in the Kattegat Sea found that harbor porpoise activity increased at a stony reef after fishing was prohibited and the reef was restored.",
    "citations": [
      "2917"
    ]
  },
  {
    "statement": "A study in the Indian Ocean found that a beach with fully prohibited human access had fewer Australian sea lions showing aggression or retreating compared to a beach with partial access restrictions.",
    "citations": [
      "2917"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of directly legally protecting marine and freshwater mammal species.",
    "citations": [
      "2923"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of enforcing existing legislation for habitat protection.",
    "citations": [
      "2916"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of establishing networks of legally protected areas.",
    "citations": [
      "2913"
    ]
  }
]

[
  {
    "statement": "The evidence for interventions aimed at reducing lethal vessel collisions with marine mammals is extremely limited.",
    "citations": []
  },
  {
    "statement": "Among the various intervention strategies examined, only setting and enforcing vessel speed limits has been evaluated with actual evidence.",
    "citations": []
  },
  {
    "statement": "Two studies evaluated the effects of setting and enforcing vessel speed limits.",
    "citations": [
      "2777"
    ]
  },
  {
    "statement": "One before-and-after study in the Indian River estuarine system found similar numbers of manatee deaths before and after vessel speed limits were set in 'zones'.",
    "citations": [
      "2777"
    ]
  },
  {
    "statement": "Fewer manatee deaths were recorded in the Indian River estuarine system after speed limits were set and enforced in all areas.",
    "citations": [
      "2777"
    ]
  },
  {
    "statement": "A before-and-after study in the North Atlantic Ocean found that setting vessel speed limits during specific periods in key habitats resulted in fewer North Atlantic right whale deaths caused by collisions.",
    "citations": [
      "2777"
    ]
  },
  {
    "statement": "No studies were found evaluating the effectiveness of diverting shipping routes.",
    "citations": [
      "2754"
    ]
  },
  {
    "statement": "No studies were found evaluating the effectiveness of using observers on board vessels to detect mammals.",
    "citations": [
      "2755"
    ]
  },
  {
    "statement": "No studies were found evaluating the effectiveness of reducing shipping along inland waterways.",
    "citations": [
      "2763"
    ]
  },
  {
    "statement": "No studies were found evaluating the effectiveness of developing and implementing regulations for operating vessels around mammals.",
    "citations": [
      "2758"
    ]
  },
  {
    "statement": "No studies were found evaluating the effectiveness of using remote tools to detect mammals.",
    "citations": [
      "2757"
    ]
  },
  {
    "statement": "No studies were found evaluating the effectiveness of using real-time automated tools on board vessels to detect mammals.",
    "citations": [
      "2756"
    ]
  },
  {
    "statement": "No studies were found evaluating the effectiveness of limiting vessel traffic in shallow rivers.",
    "citations": [
      "2764"
    ]
  },
  {
    "statement": "No studies were found evaluating the effectiveness of using acoustic devices on moving vessels.",
    "citations": [
      "2761"
    ]
  },
  {
    "statement": "No studies were found evaluating the effectiveness of providing training to vessel operators on mammal behaviour and appropriate avoidance techniques.",
    "citations": [
      "2759"
    ]
  }
]

[
  {
    "statement": "Based on studies from the Pacific and Tasman Sea regions, marine mammal translocation outcomes vary significantly depending on conservation goals.",
    "citations": []
  },
  {
    "statement": "For population re-establishment goals in the North Pacific Ocean, studies on Hawaiian monk seals showed positive outcomes.",
    "citations": [
      "2930"
    ]
  },
  {
    "statement": "50-83% of translocated Hawaiian monk seal pups survived for at least one year.",
    "citations": [
      "2930"
    ]
  },
  {
    "statement": "Translocated Hawaiian monk seal pups had similar survival rates to non-translocated pups born at release sites.",
    "citations": [
      "2930"
    ]
  },
  {
    "statement": "Translocated Hawaiian monk seal pups had greater survival rates than non-translocated pups remaining at the original site.",
    "citations": [
      "2930"
    ]
  },
  {
    "statement": "More than a quarter of translocated Hawaiian monk seals reproduced.",
    "citations": [
      "2930"
    ]
  },
  {
    "statement": "More than a quarter of translocated Hawaiian monk seals survived when translocation was combined with at least seven other survival enhancement interventions.",
    "citations": [
      "2930"
    ]
  },
  {
    "statement": "Translocated Hawaiian monk seal pups showed similar dispersal times to non-translocated seal pups born at release sites.",
    "citations": [
      "2930"
    ]
  },
  {
    "statement": "For human-wildlife conflict reduction goals in the Tasman Sea and Southern Ocean around Tasmania, two studies found that translocation was less effective.",
    "citations": [
      "2776"
    ]
  },
  {
    "statement": "More than half of Australian and New Zealand fur seals translocated away from salmon farms returned to the original location.",
    "citations": [
      "2776"
    ]
  },
  {
    "statement": "Nearly all of Australian and New Zealand fur seals translocated away from salmon farms returned to the original location.",
    "citations": [
      "2776"
    ]
  }
]

[
  {
    "statement": "Evidence for long-term survival of marine mammals following rescue or rehabilitation and release comes from multiple studies.",
    "citations": []
  },
  {
    "statement": "In 21 studies of rehabilitated and released injured, sick or weak marine mammals, 10-100% of dolphins, porpoises, whales, seals, sea lions and manatees survived.",
    "citations": [
      "2925"
    ]
  },
  {
    "statement": "The survival of these rehabilitated marine mammals was monitored during post-release periods ranging from three days to five years.",
    "citations": [
      "2925"
    ]
  },
  {
    "statement": "In seven studies of rescued and released stranded or trapped marine mammals, 17-100% of Atlantic white-sided dolphins, short-beaked common dolphins, common bottlenose dolphins, long-finned pilot whales, short-finned pilot whales, and Cape fur seals survived.",
    "citations": [
      "2924"
    ]
  },
  {
    "statement": "The survival of these rescued marine mammals was monitored during post-release periods ranging from three weeks to three years.",
    "citations": [
      "2924"
    ]
  },
  {
    "statement": "More than a quarter of rehabilitated and released Hawaiian monk seals reproduced.",
    "citations": [
      "2925"
    ]
  },
  {
    "statement": "A stranded common bottlenose dolphin was observed with a calf a year after its rescue and release.",
    "citations": [
      "2924"
    ]
  },
  {
    "statement": "More than a quarter of Hawaiian monk seals survived after rescue, release and other interventions.",
    "citations": [
      "2924"
    ]
  },
  {
    "statement": "Approximately three-quarters of Antillean manatees that were captive-reared and released were known to survive for at least one year.",
    "citations": [
      "2926"
    ]
  },
  {
    "statement": "Approximately two-thirds of Florida manatees that were captive-reared and released were known to survive for at least one year.",
    "citations": [
      "2926"
    ]
  },
  {
    "statement": "Some captive-reared and released manatees survived for more than seven years.",
    "citations": [
      "2926"
    ]
  },
  {
    "statement": "Captive-reared and released Pacific harbour seal pups had similar survival estimates to wild pups.",
    "citations": [
      "2926"
    ]
  },
  {
    "statement": "Two of three Antillean manatees born in captivity survived for at least one year without further intervention after release.",
    "citations": [
      "2933"
    ]
  },
  {
    "statement": "Two of fourteen Florida manatees born in captivity survived for at least one year without further intervention after release.",
    "citations": [
      "2933"
    ]
  }
]

[
  {
    "statement": "Several actions are available to reduce human-wildlife conflict at commercial fisheries in riverine systems based on documented studies.",
    "citations": []
  },
  {
    "statement": "Installing barriers at wild fisheries has been tested.",
    "citations": []
  },
  {
    "statement": "A study in the Puntledge River found that installing a 'cork line' barrier did not deter harbour seals from feeding on salmon released from a hatchery.",
    "citations": [
      "2824"
    ]
  },
  {
    "statement": "Anti-predator nets can be effective when properly maintained.",
    "citations": [
      "2774"
    ]
  },
  {
